// Canonical Tauri v2 crate, config & entrypoint template emitters for `scripts/desktop/generate-tauri-steam.mjs`.
import { deriveWixVersion } from './desktop-config.mjs';
export { renderSteamBridgeRs } from './steam-bridge-rs-template.mjs';

export function renderCargoToml(cfg) {
  return [
    '# Generated by scripts/desktop/generate-tauri-steam.mjs — regenerate rather than hand-editing.',
    '[package]',
    'name = "out-of-credits-desktop"',
    `version = "${cfg.version}"`,
    `description = ${JSON.stringify(cfg.description)}`,
    'authors = ["Out Of Credits Studio"]',
    'license = "MIT"',
    'edition = "2021"',
    'rust-version = "1.77.2"',
    '',
    '[lib]',
    'name = "out_of_credits_lib"',
    'crate-type = ["staticlib", "cdylib", "rlib"]',
    '',
    '[build-dependencies]',
    'tauri-build = { version = "2.0.5", features = [] }',
    '',
    '[dependencies]',
    'serde = { version = "1.0.217", features = ["derive"] }',
    'serde_json = "1.0.138"',
    'tauri = { version = "2.2.5", features = [] }',
    'steamworks = { version = "0.11.0", optional = true }',
    '',
    '[features]',
    'default = []',
    'custom-protocol = ["tauri/custom-protocol"]',
    'steam = ["dep:steamworks"]',
    '',
  ].join('\n');
}

export function renderBuildRs() {
  return [
    'fn stage_steam_redistributable() {',
    '    let Ok(out_dir) = std::env::var("OUT_DIR") else { return };',
    '    let out_path = std::path::PathBuf::from(out_dir);',
    '    let Some(build_dir) = out_path.ancestors().find(|p| p.file_name() == Some(std::ffi::OsStr::new("build"))) else { return };',
    '    let Some(profile_dir) = build_dir.parent() else { return };',
    '    let deps_dir = profile_dir.join("deps");',
    '    let _ = std::fs::create_dir_all(&deps_dir);',
    '    let manifest_redist = std::env::var("CARGO_MANIFEST_DIR").ok().map(|m| std::path::PathBuf::from(m).join("steam-redist"));',
    '    if let Some(ref dir) = manifest_redist {',
    '        let _ = std::fs::create_dir_all(dir);',
    '    }',
    '    let Ok(entries) = std::fs::read_dir(build_dir) else { return };',
    '    let mut sys_outs = Vec::new();',
    '    for entry in entries.flatten() {',
    '        let name = entry.file_name();',
    '        let name_s = name.to_string_lossy();',
    '        if name_s.starts_with("steamworks-sys-") {',
    '            sys_outs.push(entry.path().join("out"));',
    '        } else if name_s == "steamworks-sys" {',
    '            if let Ok(sub_entries) = std::fs::read_dir(entry.path()) {',
    '                for sub in sub_entries.flatten() {',
    '                    sys_outs.push(sub.path().join("out"));',
    '                }',
    '            }',
    '        }',
    '    }',
    '    for sys_out in sys_outs {',
    '        for lib_name in ["libsteam_api.dylib", "steam_api64.dll", "steam_api.dll", "libsteam_api.so"] {',
    '            let src = sys_out.join(lib_name);',
    '            if src.is_file() {',
    '                let _ = std::fs::copy(&src, profile_dir.join(lib_name));',
    '                if deps_dir.is_dir() {',
    '                    let _ = std::fs::copy(&src, deps_dir.join(lib_name));',
    '                }',
    '                if let Some(ref dir) = manifest_redist {',
    '                    let _ = std::fs::copy(&src, dir.join(lib_name));',
    '                }',
    '            }',
    '        }',
    '    }',
    '}',
    '',
    'fn main() {',
    '    #[cfg(feature = "steam")]',
    '    {',
    '        println!("cargo:warning=Building Out Of Credits with Steamworks SDK (`steam` Cargo feature enabled)");',
    '        match std::env::var("CARGO_CFG_TARGET_OS").as_deref() {',
    '            Ok("linux") => {',
    '                println!("cargo:rustc-link-arg=-Wl,-rpath,$ORIGIN:$ORIGIN/../lib/out-of-credits-desktop:$ORIGIN/../lib/Out Of Credits:$ORIGIN/../lib");',
    '            }',
    '            Ok("macos") => {',
    '                println!("cargo:rustc-link-arg=-Wl,-rpath,@executable_path,-rpath,@executable_path/../Frameworks");',
    '            }',
    '            _ => {}',
    '        }',
    '        stage_steam_redistributable();',
    '    }',
    '    #[cfg(not(feature = "steam"))]',
    '    let _ = stage_steam_redistributable as fn();',
    '    tauri_build::build();',
    '}',
    '',
  ].join('\n');
}

export function renderTauriConf(cfg) {
  const conf = {
    $schema: 'https://schema.tauri.app/config/2',
    productName: cfg.productName,
    version: cfg.version,
    identifier: cfg.identifier,
    build: {
      beforeDevCommand: 'npm start',
      devUrl: 'http://localhost:5400',
      beforeBuildCommand: 'npm run build && node scripts/desktop/generate-tauri-steam.mjs',
      frontendDist: '../dist',
    },
    app: {
      windows: [
        {
          label: 'main',
          title: cfg.productName,
          width: 1440,
          height: 900,
          minWidth: 1100,
          minHeight: 720,
          resizable: true,
          fullscreen: false,
        },
      ],
      security: {
        // Prevent Tauri compile-time nonce/hash injection from canceling `'unsafe-inline'` on runtime styles and iframe[srcdoc].
        dangerousDisableAssetCspModification: true,
        // Strictly offline local origin only (zero remote domains). `'unsafe-eval'` is required by Level 6 `validateJsCart` and Laptop Lab's blob: Worker.
        csp: "default-src 'self' blob: data: tauri: http://tauri.localhost https://tauri.localhost; img-src 'self' data: blob:; font-src 'self' data:; style-src 'self' 'unsafe-inline'; script-src 'self' 'unsafe-inline' 'unsafe-eval' blob:; worker-src 'self' blob:; frame-src 'self' blob: data:; connect-src 'self' ipc: http://ipc.localhost https://ipc.localhost tauri: http://tauri.localhost https://tauri.localhost",
      },
    },
    bundle: {
      active: true,
      targets: ['dmg', 'app', 'msi', 'nsis', 'deb', 'appimage'],
      category: 'Game',
      shortDescription: 'A 90s comic-book action-puzzle game where the only controller is a Unix terminal.',
      longDescription: cfg.description,
      icon: [
        'icons/32x32.png',
        'icons/128x128.png',
        'icons/128x128@2x.png',
        'icons/icon.icns',
        'icons/icon.ico',
      ],
      ...(String(cfg.version).includes('-')
        ? { windows: { wix: { version: deriveWixVersion(cfg.version) } } }
        : {}),
    },
  };
  return `${JSON.stringify(conf, null, 2)}\n`;
}

export function renderCapabilityJson() {
  return `${JSON.stringify(
    {
      $schema: '../gen/schemas/desktop-schema.json',
      identifier: 'default',
      description: 'Least-privilege capabilities for the main Out Of Credits desktop window.',
      windows: ['main'],
      permissions: ['core:default'],
    },
    null,
    2,
  )}\n`;
}

export function renderAchievementsManifestRs(achievements, steamAppId) {
  const rows = achievements.map((a) => `    ("${a.id}", "${a.steamApiName}"),`).join('\n');
  const appIdExpr = steamAppId ? `Some(${steamAppId}u32)` : 'None';
  return [
    '// Generated 1:1 from src/chapters/achievements.ts — do not hand-edit.',
    `pub const DEFAULT_STEAM_APP_ID: Option<u32> = ${appIdExpr};`,
    '',
    'pub const ACHIEVEMENT_KEYS: &[(&str, &str)] = &[',
    rows,
    '];',
    '',
    'pub fn is_known_api_name(api_name: &str) -> bool {',
    '    ACHIEVEMENT_KEYS.iter().any(|(_, key)| *key == api_name)',
    '}',
    '',
  ].join('\n');
}

export function renderLibRs() {
  return [
    'pub mod achievements_manifest;',
    'pub mod steam;',
    '',
    'use steam::{DesktopBridge, SteamStatusReply, SyncReply, UnlockReply};',
    'use tauri::{Manager, State};',
    '',
    '#[tauri::command]',
    'fn steam_status(bridge: State<\'_, DesktopBridge>) -> SteamStatusReply { bridge.status() }',
    '',
    '#[tauri::command]',
    'fn steam_unlock_achievement(bridge: State<\'_, DesktopBridge>, api_name: String) -> Result<UnlockReply, String> { bridge.unlock(&api_name) }',
    '',
    '#[tauri::command]',
    'fn steam_sync_achievements(bridge: State<\'_, DesktopBridge>, api_names: Vec<String>) -> Result<SyncReply, String> { bridge.sync_many(&api_names) }',
    '',
    '#[tauri::command]',
    'fn steam_clear_achievement(bridge: State<\'_, DesktopBridge>, api_name: String) -> Result<bool, String> { bridge.clear(&api_name) }',
    '',
    '#[tauri::command]',
    'fn desktop_read_save_bundle(bridge: State<\'_, DesktopBridge>) -> Option<String> { bridge.read_save_bundle() }',
    '',
    '#[tauri::command]',
    'fn desktop_write_save_bundle(bridge: State<\'_, DesktopBridge>, bundle_json: String) -> Result<bool, String> { bridge.write_save_bundle(&bundle_json) }',
    '',
    '#[tauri::command]',
    'fn desktop_export_json_file(bridge: State<\'_, DesktopBridge>, filename: String, json_content: String) -> Result<String, String> { bridge.export_json_file(&filename, &json_content) }',
    '',
    '#[tauri::command]',
    'fn desktop_open_external_url(bridge: State<\'_, DesktopBridge>, url: String) -> Result<bool, String> { bridge.open_external_url(&url) }',
    '',
    '#[tauri::command]',
    'fn steam_show_floating_keyboard(bridge: State<\'_, DesktopBridge>, x: i32, y: i32, width: i32, height: i32) -> bool { bridge.show_floating_keyboard(x, y, width, height) }',
    '',
    '#[cfg_attr(mobile, tauri::mobile_entry_point)]',
    'pub fn run() {',
    '    tauri::Builder::default()',
    '        .setup(|app| {',
    '            let data_dir = app.path().app_data_dir().unwrap_or_else(|_| std::env::temp_dir().join("out-of-credits"));',
    '            let dl_dir = app.path().download_dir().unwrap_or_else(|_| data_dir.clone());',
    '            app.manage(DesktopBridge::with_dirs(data_dir, dl_dir));',
    '            Ok(())',
    '        })',
    '        .invoke_handler(tauri::generate_handler![',
    '            steam_status,',
    '            steam_unlock_achievement,',
    '            steam_sync_achievements,',
    '            steam_clear_achievement,',
    '            desktop_read_save_bundle,',
    '            desktop_write_save_bundle,',
    '            desktop_export_json_file,',
    '            desktop_open_external_url,',
    '            steam_show_floating_keyboard',
    '        ])',
    '        .run(tauri::generate_context!())',
    '        .expect("error while running Out Of Credits desktop shell");',
    '}',
    '',
  ].join('\n');
}

export function renderMainRs() {
  return [
    '#![cfg_attr(not(debug_assertions), windows_subsystem = "windows")]',
    '',
    'fn main() {',
    '    out_of_credits_lib::run();',
    '}',
    '',
  ].join('\n');
}
